import org.apache.lucene.document.ShapeField;
import org.apache.lucene.util.GeoEncodingUtils;

public class DebugBranches {
  static void enc(int ay, int ax, boolean ab, int by, int bx, boolean bc, int cy, int cx, boolean ca, String label) {
    byte[] b = new byte[7 * ShapeField.BYTES];
    ShapeField.encodeTriangle(b, ay, ax, ab, by, bx, bc, cy, cx, ca);
    ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
    ShapeField.decodeTriangle(b, dt);
    System.out.println(label + ": " + dt + " type=" + dt.type);
  }

  public static void main(String[] args) {
    int y0 = GeoEncodingUtils.encodeLatitude(0.0);
    int x0 = GeoEncodingUtils.encodeLongitude(0.0);
    int x1 = GeoEncodingUtils.encodeLongitude(1.0);
    int y1 = GeoEncodingUtils.encodeLatitude(1.0);
    // branch a==b: retained segment a..c, spanning edges bc and ca
    enc(y0, x0, false, y0, x0, true, y1, x1, false, "a==b (bc=true, ca=false): ");
    enc(y0, x0, true,  y0, x0, false, y1, x1, false, "a==b (ab=true, others false): ");
    // branch a==c: retained segment a..b, spanning edges ab and bc
    enc(y0, x0, false, y1, x1, true, y0, x0, true, "a==c (ab=false, bc=true): ");
    enc(y0, x0, true, y1, x1, false, y0, x0, false, "a==c (ab=true, bc=false): ");
    // branch b==c: retained segment a..b, spanning edges ab and ca
    enc(y0, x0, false, y1, x1, true, y1, x1, true, "b==c (ab=false, ca=true): ");
    enc(y0, x0, true, y1, x1, true, y1, x1, false, "b==c (ab=true): ");
  }
}
EOF
